#!/usr/bin/env python3
"""Tests for the version-rewriting half of release.py.

The publish/git/gh half of `release()` can only run in CI with real
credentials, but the file rewriting (`apply_version_bump`) is pure and is
exactly where the inversion refactor broke the release: the frontend crate
started depending on `hegeltest-c` via a `=`-pinned path dependency, and the
old hardcoded bump list never touched it, so `cargo update --workspace` blew
up with "failed to select a version for the requirement `hegeltest-c =
0.19.1`" after the package version had already moved to 0.19.2.
"""

from __future__ import annotations

import sys
import tempfile
import unittest
from pathlib import Path

sys.path.insert(0, str(Path(__file__).resolve().parent))

import json
import re
import release
from release import CPP, JAVA, LIBHEGEL, OCAML, PYTHON, RUST, TYPESCRIPT

RUST_CARGO = """\
[package]
name = "hegeltest"
version = "0.19.1"
edition = "2024"

[dependencies]
hegeltest-macros = { version = "=0.19.1", path = "macros" }
hegeltest-c = { version = "=0.5.0", path = "../../libhegel", default-features = false, optional = true }
serde = { version = "1.0.103", features = ["derive"] }

[features]
static-engine = ["dep:hegeltest-c"]
"""

MACROS_CARGO = """\
[package]
name = "hegeltest-macros"
version = "0.19.1"
edition = "2024"

[dependencies]
syn = { version = "2.0", features = ["full"] }
"""

# libhegel does not depend on hegeltest. It must keep bumping cleanly (its
# package version moves; it has no internal deps to touch) so that a future
# re-inversion is the only thing that re-adds one.
C_CARGO = """\
[package]
name = "hegeltest-c"
version = "0.5.0"
edition = "2024"

[dependencies]
ciborium = "0.2.2"
serde = { version = "1.0.103", features = ["derive"] }
"""

# The Python extension builds libhegel from the tree, so its dependency is an
# unpinned path: nothing to bump but its own version.
PYTHON_CARGO = """\
[package]
name = "hegel-python"
version = "0.1.0"
edition = "2024"

[dependencies]
pyo3 = { version = "0.29", features = ["num-bigint"] }
hegeltest-c = { path = "../../libhegel", default-features = false, features = ["std"] }
"""

# The TypeScript frontend's version lives in npm manifests: package.json and
# the lockfile, which repeats it for the root package. The engine version it
# ships is a generated source file.
TYPESCRIPT_PACKAGE = {
    "name": "@hegeldev/hegel",
    "version": "0.4.10",
    "dependencies": {"koffi": "^3.0.2"},
}
TYPESCRIPT_LOCK = {
    "name": "@hegeldev/hegel",
    "version": "0.4.10",
    "lockfileVersion": 3,
    "packages": {
        "": {"name": "@hegeldev/hegel", "version": "0.4.10"},
        "node_modules/koffi": {"version": "3.0.2"},
    },
}
TYPESCRIPT_PIN = (
    "// Generated by scripts/engine.mjs from libhegel/Cargo.toml. Do not edit.\n"
    'export const LIBHEGEL_VERSION = "0.5.0";\n'
)

# The C++ frontend's version is the project() version of its CMakeLists.txt.
CPP_CMAKE = """\
cmake_minimum_required(VERSION 3.14)
project(hegel-cpp VERSION 0.13.1 LANGUAGES CXX)

set(CMAKE_CXX_STANDARD 20)
"""

# The Java frontend's version lives in Maven poms: the parent pom's project
# version, repeated by each module pom's <parent> reference (the modules
# declare no version of their own).
JAVA_PARENT_POM = """\
<project>
  <modelVersion>4.0.0</modelVersion>
  <groupId>dev.hegel</groupId>
  <artifactId>hegel-parent</artifactId>
  <version>0.10.2</version>
  <packaging>pom</packaging>
  <dependencies>
    <dependency>
      <groupId>org.junit.jupiter</groupId>
      <artifactId>junit-jupiter</artifactId>
      <version>5.11.4</version>
    </dependency>
  </dependencies>
</project>
"""
JAVA_MODULE_POM = """\
<project>
  <modelVersion>4.0.0</modelVersion>
  <parent>
    <groupId>dev.hegel</groupId>
    <artifactId>hegel-parent</artifactId>
    <version>0.10.2</version>
  </parent>
  <artifactId>hegel</artifactId>
  <dependencies>
    <dependency>
      <groupId>net.java.dev.jna</groupId>
      <artifactId>jna</artifactId>
      <version>5.17.0</version>
    </dependency>
  </dependencies>
</project>
"""

# The OCaml frontend's version is the dune-project `(version ...)`, which
# dune copies into each generated .opam file.
OCAML_DUNE_PROJECT = """\
(lang dune 3.16)

(name hegel)

(version 0.26.3)

(generate_opam_files true)

(package
 (name hegel)
 (depends
  (ctypes
   (>= 0.20))))
"""


def ocaml_opam(name: str) -> str:
    return f"""\
# This file is generated by dune, edit dune-project instead
opam-version: "2.0"
version: "0.26.3"
synopsis: "{name}"
depends: [
  "dune" {{>= "3.16"}}
  "ctypes" {{>= "0.20"}}
]
"""


JAVA_README = """\
<dependency>
  <groupId>dev.hegel</groupId>
  <artifactId>hegel</artifactId>
  <version>0.10.2</version>
</dependency>

testImplementation("dev.hegel:hegel:0.10.2") // or "dev.hegel:hegel-jna:0.10.2"

Requires Java 10.10.2.1 or 0.10.20.
"""


CPP_README = """\
FetchContent_Declare(
    hegel
    GIT_REPOSITORY https://github.com/hegeldev/hegel.git
    GIT_TAG frontends/cpp/0.13.1
    SOURCE_SUBDIR frontends/cpp
)
"""


CPP_HEGEL_H = """\
/**
 * @code{.cmake}
 * FetchContent_Declare(
 *     hegel
 *     GIT_REPOSITORY https://github.com/hegeldev/hegel.git
 *     GIT_TAG frontends/cpp/0.13.1
 *     SOURCE_SUBDIR frontends/cpp
 * )
 * @endcode
 */
"""


PATCH = ("patch", "This patch does a thing.")
MINOR = ("minor", "This release breaks the C ABI.")


class ApplyVersionBumpTest(unittest.TestCase):
    def setUp(self) -> None:
        self._tmp = tempfile.TemporaryDirectory()
        self.root = Path(self._tmp.name)
        for rel, text in [
            ("frontends/rust/Cargo.toml", RUST_CARGO),
            ("frontends/rust/macros/Cargo.toml", MACROS_CARGO),
            ("libhegel/Cargo.toml", C_CARGO),
            ("frontends/python/Cargo.toml", PYTHON_CARGO),
            ("frontends/typescript/package.json", json.dumps(TYPESCRIPT_PACKAGE, indent=2) + "\n"),
            ("frontends/typescript/package-lock.json", json.dumps(TYPESCRIPT_LOCK, indent=2) + "\n"),
            ("frontends/typescript/src/libhegel-version.ts", TYPESCRIPT_PIN),
            ("frontends/cpp/CMakeLists.txt", CPP_CMAKE),
            ("frontends/cpp/README.md", CPP_README),
            ("frontends/cpp/include/hegel/hegel.h", CPP_HEGEL_H),
            ("frontends/java/pom.xml", JAVA_PARENT_POM),
            ("frontends/java/hegel-lowlevel/pom.xml", JAVA_MODULE_POM),
            ("frontends/java/hegel/pom.xml", JAVA_MODULE_POM),
            ("frontends/java/hegel-jna/pom.xml", JAVA_MODULE_POM),
            ("frontends/java/README.md", JAVA_README),
            ("frontends/ocaml/dune-project", OCAML_DUNE_PROJECT),
            *((f"frontends/ocaml/{name}.opam", ocaml_opam(name)) for name in OCAML.crates),
        ]:
            path = self.root / rel
            path.parent.mkdir(parents=True, exist_ok=True)
            path.write_text(text)

    def tearDown(self) -> None:
        self._tmp.cleanup()

    def read(self, rel: str) -> str:
        return (self.root / rel).read_text()

    def test_bumps_each_package_to_its_own_version(self) -> None:
        # The Rust frontend (hegeltest + macros), libhegel, the Python
        # frontend and the TypeScript frontend version independently.
        release.apply_version_bump(
            self.root,
            {
                RUST: "0.19.2",
                LIBHEGEL: "0.6.0",
                PYTHON: "0.1.1",
                TYPESCRIPT: "0.4.11",
                CPP: "0.13.2",
            },
        )
        for rel in RUST.manifests:
            self.assertIn('version = "0.19.2"', self.read(rel), rel)
            self.assertNotIn('version = "0.19.1"', self.read(rel), rel)
        self.assertIn('version = "0.6.0"', self.read("libhegel/Cargo.toml"))
        self.assertNotIn('version = "0.5.0"', self.read("libhegel/Cargo.toml"))
        self.assertIn('version = "0.1.1"', self.read("frontends/python/Cargo.toml"))
        self.assertIn(
            "project(hegel-cpp VERSION 0.13.2 LANGUAGES CXX)",
            self.read("frontends/cpp/CMakeLists.txt"),
        )
        package = json.loads(self.read("frontends/typescript/package.json"))
        self.assertEqual(package["version"], "0.4.11")
        lock = json.loads(self.read("frontends/typescript/package-lock.json"))
        self.assertEqual(lock["version"], "0.4.11")
        self.assertEqual(lock["packages"][""]["version"], "0.4.11")
        self.assertEqual(lock["packages"]["node_modules/koffi"]["version"], "3.0.2")

    def test_bumps_the_maven_parent_and_every_module_parent_reference(self) -> None:
        # Only the project version (parent pom) and the <parent> references
        # (module poms) move: dependency versions stay where they are.
        release.apply_version_bump(self.root, {JAVA: "0.10.3"})
        self.assertEqual(
            self.read("frontends/java/pom.xml"), JAVA_PARENT_POM.replace("0.10.2", "0.10.3")
        )
        for rel in JAVA.manifests[1:]:
            self.assertEqual(self.read(rel), JAVA_MODULE_POM.replace("0.10.2", "0.10.3"), rel)

    def test_rewrites_the_version_in_install_docs(self) -> None:
        # Only whole mentions of the old version move, not longer numbers
        # that contain it.
        release.apply_version_bump(self.root, {JAVA: "0.11.0"})
        self.assertEqual(
            self.read("frontends/java/README.md"),
            JAVA_README.replace("<version>0.10.2<", "<version>0.11.0<")
            .replace("hegel:0.10.2", "hegel:0.11.0")
            .replace("hegel-jna:0.10.2", "hegel-jna:0.11.0"),
        )

    def test_rewrites_the_cpp_fetchcontent_tags(self) -> None:
        # The README's CMake snippet and the Doxygen copy of it in hegel.h
        # both name the release tag.
        release.apply_version_bump(self.root, {CPP: "0.14.0"})
        self.assertEqual(
            self.read("frontends/cpp/README.md"),
            CPP_README.replace("frontends/cpp/0.13.1", "frontends/cpp/0.14.0"),
        )
        self.assertEqual(
            self.read("frontends/cpp/include/hegel/hegel.h"),
            CPP_HEGEL_H.replace("frontends/cpp/0.13.1", "frontends/cpp/0.14.0"),
        )

    def test_install_docs_in_the_checkout_name_the_current_version(self) -> None:
        for component in release.COMPONENTS:
            version = release.current_version(component.manifest())
            for doc in component.install_docs:
                self.assertIn(version, (release.ROOT / doc).read_text(), doc)

    def test_an_install_doc_without_the_version_is_an_error(self) -> None:
        (self.root / "frontends/java/README.md").write_text("no version here\n")
        with self.assertRaises(ValueError):
            release.apply_version_bump(self.root, {JAVA: "0.11.0"})

    def test_bumps_the_dune_project_and_every_opam_file(self) -> None:
        release.apply_version_bump(self.root, {OCAML: "0.26.4"})
        self.assertEqual(
            self.read("frontends/ocaml/dune-project"),
            OCAML_DUNE_PROJECT.replace("0.26.3", "0.26.4"),
        )
        for name in OCAML.crates:
            self.assertEqual(
                self.read(f"frontends/ocaml/{name}.opam"),
                ocaml_opam(name).replace("0.26.3", "0.26.4"),
                name,
            )

    def test_rewrites_npm_manifests_in_npm_style(self) -> None:
        # npm writes two-space indented JSON with a trailing newline; keeping
        # that layout makes the release commit's diff only the version lines.
        release.apply_version_bump(self.root, {TYPESCRIPT: "0.4.11"})
        self.assertEqual(
            self.read("frontends/typescript/package.json"),
            json.dumps({**TYPESCRIPT_PACKAGE, "version": "0.4.11"}, indent=2) + "\n",
        )

    def test_leaves_unreleased_components_alone(self) -> None:
        release.apply_version_bump(self.root, {PYTHON: "0.1.1"})
        self.assertEqual(self.read("frontends/rust/Cargo.toml"), RUST_CARGO)
        self.assertEqual(self.read("frontends/rust/macros/Cargo.toml"), MACROS_CARGO)
        self.assertEqual(self.read("libhegel/Cargo.toml"), C_CARGO)
        self.assertIn('version = "0.1.1"', self.read("frontends/python/Cargo.toml"))
        self.assertEqual(
            self.read("frontends/typescript/package.json"),
            json.dumps(TYPESCRIPT_PACKAGE, indent=2) + "\n",
        )
        self.assertEqual(self.read("frontends/typescript/src/libhegel-version.ts"), TYPESCRIPT_PIN)
        self.assertEqual(self.read("frontends/java/pom.xml"), JAVA_PARENT_POM)
        self.assertEqual(self.read("frontends/java/hegel/pom.xml"), JAVA_MODULE_POM)
        self.assertEqual(self.read("frontends/ocaml/dune-project"), OCAML_DUNE_PROJECT)
        self.assertEqual(self.read("frontends/ocaml/hegel.opam"), ocaml_opam("hegel"))

    def test_engine_pin_follows_the_libhegel_version(self) -> None:
        # The TypeScript frontend's generated pin moves with libhegel whether
        # or not the frontend has a release of its own, and stays put on a
        # frontend-only release.
        release.apply_version_bump(self.root, {LIBHEGEL: "0.6.0"})
        self.assertEqual(
            self.read("frontends/typescript/src/libhegel-version.ts"),
            TYPESCRIPT_PIN.replace("0.5.0", "0.6.0"),
        )
        release.apply_version_bump(self.root, {TYPESCRIPT: "0.4.11"})
        self.assertEqual(
            self.read("frontends/typescript/src/libhegel-version.ts"),
            TYPESCRIPT_PIN.replace("0.5.0", "0.6.0"),
        )

    def test_engine_pin_must_be_unambiguous(self) -> None:
        pin = self.root / "frontends/typescript/src/libhegel-version.ts"
        pin.write_text("export const OTHER = 1;\n")
        with self.assertRaises(ValueError):
            release.set_engine_pin(pin, "0.6.0")

    def test_bumps_internal_path_dependency_pins_per_crate(self) -> None:
        # Each internal path dep in the hegeltest manifest must follow its own
        # crate's version, or `cargo update --workspace` fails: the macros pin
        # tracks the frontend version, the hegeltest-c pin the libhegel version.
        release.apply_version_bump(self.root, {RUST: "0.19.2", LIBHEGEL: "0.6.0"})
        rust_text = self.read("frontends/rust/Cargo.toml")
        self.assertIn(
            'hegeltest-macros = { version = "=0.19.2", path = "macros" }',
            rust_text,
        )
        self.assertIn(
            'hegeltest-c = { version = "=0.6.0", path = "../../libhegel", '
            "default-features = false, optional = true }",
            rust_text,
        )

    def test_pins_follow_an_unreleased_crate_too(self) -> None:
        # A frontend-only release leaves libhegel where it is, and the pin on
        # it must stay at that version rather than be dropped or moved.
        release.apply_version_bump(self.root, {RUST: "0.19.2"})
        rust_text = self.read("frontends/rust/Cargo.toml")
        self.assertIn('hegeltest-macros = { version = "=0.19.2", path = "macros" }', rust_text)
        self.assertIn('hegeltest-c = { version = "=0.5.0", path = "../../libhegel"', rust_text)

    def test_leaves_external_and_unpinned_dependencies_untouched(self) -> None:
        release.apply_version_bump(
            self.root, {RUST: "0.19.2", LIBHEGEL: "0.6.0", PYTHON: "0.1.1"}
        )
        rust_text = self.read("frontends/rust/Cargo.toml")
        # External deps carry no `path =`, so they must be left alone — and the
        # `static-engine` feature reference is not a version pin either.
        self.assertIn('serde = { version = "1.0.103", features = ["derive"] }', rust_text)
        self.assertIn('static-engine = ["dep:hegeltest-c"]', rust_text)
        # The Python crate's path dependency carries no pin to move.
        self.assertIn(
            'hegeltest-c = { path = "../../libhegel", default-features = false, features = ["std"] }',
            self.read("frontends/python/Cargo.toml"),
        )


CURRENT = {
    RUST: "0.19.1",
    LIBHEGEL: "0.5.0",
    PYTHON: "0.1.0",
    TYPESCRIPT: "0.4.10",
    CPP: "0.13.1",
    JAVA: "0.10.2",
    OCAML: "0.26.3",
}


class PlanReleaseTest(unittest.TestCase):
    def test_rust_only_bumps_rust_and_leaves_the_rest(self) -> None:
        plan = release.plan_release(CURRENT, {RUST: PATCH})
        self.assertEqual(plan, {RUST: ("0.19.2", "This patch does a thing.")})

    def test_python_only_bumps_python_and_leaves_the_rest(self) -> None:
        plan = release.plan_release(CURRENT, {PYTHON: PATCH})
        self.assertEqual(plan, {PYTHON: ("0.1.1", "This patch does a thing.")})

    def test_c_only_patch_bumps_every_frontend_with_an_engine_entry(self) -> None:
        plan = release.plan_release(CURRENT, {LIBHEGEL: ("patch", "This patch tweaks the C ABI.")})
        self.assertEqual(
            plan,
            {
                LIBHEGEL: ("0.5.1", "This patch tweaks the C ABI."),
                RUST: ("0.19.2", "This release updates the `hegeltest-c` dependency to 0.5.1."),
                PYTHON: ("0.1.1", "This release updates the bundled libhegel engine to 0.5.1."),
                TYPESCRIPT: (
                    "0.4.11",
                    "This release updates the bundled libhegel engine to 0.5.1.",
                ),
                CPP: (
                    "0.13.2",
                    "This release updates the bundled libhegel engine to 0.5.1.",
                ),
                JAVA: ("0.10.3", "This release updates the bundled libhegel engine to 0.5.1."),
                OCAML: ("0.26.4", "This release updates the bundled libhegel engine to 0.5.1."),
            },
        )

    def test_c_minor_is_only_a_frontend_patch(self) -> None:
        # The whole point of independent versions: a breaking C ABI change is a
        # minor bump for libhegel but only a patch for each frontend.
        plan = release.plan_release(CURRENT, {LIBHEGEL: MINOR})
        self.assertEqual(plan[LIBHEGEL], ("0.6.0", "This release breaks the C ABI."))
        self.assertEqual(plan[RUST][0], "0.19.2")
        self.assertEqual(plan[PYTHON][0], "0.1.1")
        self.assertEqual(plan[TYPESCRIPT][0], "0.4.11")
        self.assertEqual(plan[CPP][0], "0.13.2")
        self.assertEqual(plan[JAVA][0], "0.10.3")
        self.assertEqual(plan[OCAML][0], "0.26.4")

    def test_a_frontend_release_file_overrides_the_engine_entry(self) -> None:
        plan = release.plan_release(CURRENT, {RUST: PATCH, LIBHEGEL: MINOR})
        self.assertEqual(plan[RUST], ("0.19.2", "This patch does a thing."))
        self.assertEqual(plan[LIBHEGEL], ("0.6.0", "This release breaks the C ABI."))
        self.assertEqual(
            plan[PYTHON],
            ("0.1.1", "This release updates the bundled libhegel engine to 0.6.0."),
        )

    def test_absent_entries_count_as_no_release_file(self) -> None:
        plan = release.plan_release(CURRENT, {RUST: None, LIBHEGEL: None, PYTHON: PATCH})
        self.assertEqual(list(plan), [PYTHON])

    def test_typescript_only_bumps_typescript_and_leaves_the_rest(self) -> None:
        plan = release.plan_release(CURRENT, {TYPESCRIPT: PATCH})
        self.assertEqual(plan, {TYPESCRIPT: ("0.4.11", "This patch does a thing.")})

    def test_cpp_only_bumps_cpp_and_leaves_the_rest(self) -> None:
        plan = release.plan_release(CURRENT, {CPP: PATCH})
        self.assertEqual(plan, {CPP: ("0.13.2", "This patch does a thing.")})

    def test_java_only_bumps_java_and_leaves_the_rest(self) -> None:
        plan = release.plan_release(CURRENT, {JAVA: PATCH})
        self.assertEqual(plan, {JAVA: ("0.10.3", "This patch does a thing.")})

    def test_ocaml_only_bumps_ocaml_and_leaves_the_rest(self) -> None:
        plan = release.plan_release(CURRENT, {OCAML: MINOR})
        self.assertEqual(plan, {OCAML: ("0.27.0", "This release breaks the C ABI.")})


class CurrentVersionTest(unittest.TestCase):
    def test_reads_the_package_version(self) -> None:
        with tempfile.TemporaryDirectory() as tmp:
            manifest = Path(tmp) / "Cargo.toml"
            manifest.write_text(RUST_CARGO)
            self.assertEqual(release.current_version(manifest), "0.19.1")

    def test_reads_an_npm_package_version(self) -> None:
        with tempfile.TemporaryDirectory() as tmp:
            manifest = Path(tmp) / "package.json"
            manifest.write_text(json.dumps(TYPESCRIPT_PACKAGE))
            self.assertEqual(release.current_version(manifest), "0.4.10")

    def test_reads_a_cmake_project_version(self) -> None:
        with tempfile.TemporaryDirectory() as tmp:
            manifest = Path(tmp) / "CMakeLists.txt"
            manifest.write_text(CPP_CMAKE)
            self.assertEqual(release.current_version(manifest), "0.13.1")

    def test_a_cmake_manifest_without_a_project_version_is_an_error(self) -> None:
        with tempfile.TemporaryDirectory() as tmp:
            manifest = Path(tmp) / "CMakeLists.txt"
            manifest.write_text("project(hegel-cpp LANGUAGES CXX)\n")
            with self.assertRaises(ValueError):
                release.current_version(manifest)
            with self.assertRaises(ValueError):
                release.set_version(manifest, "0.13.2")

    def test_reads_a_maven_pom_version(self) -> None:
        # A module pom's first <version> is its parent reference, which is
        # the component's version too.
        with tempfile.TemporaryDirectory() as tmp:
            manifest = Path(tmp) / "pom.xml"
            manifest.write_text(JAVA_PARENT_POM)
            self.assertEqual(release.current_version(manifest), "0.10.2")
            manifest.write_text(JAVA_MODULE_POM)
            self.assertEqual(release.current_version(manifest), "0.10.2")

    def test_reads_a_dune_project_and_an_opam_version(self) -> None:
        with tempfile.TemporaryDirectory() as tmp:
            dune_project = Path(tmp) / "dune-project"
            dune_project.write_text(OCAML_DUNE_PROJECT)
            self.assertEqual(release.current_version(dune_project), "0.26.3")
            opam = Path(tmp) / "hegel.opam"
            opam.write_text(ocaml_opam("hegel"))
            self.assertEqual(release.current_version(opam), "0.26.3")


class ComponentTest(unittest.TestCase):
    def test_tags_are_path_slash_version(self) -> None:
        self.assertEqual(RUST.tag("0.23.3"), "frontends/rust/0.23.3")
        self.assertEqual(LIBHEGEL.tag("0.24.0"), "libhegel/0.24.0")
        self.assertEqual(PYTHON.tag("0.2.0"), "frontends/python/0.2.0")
        self.assertEqual(TYPESCRIPT.tag("0.4.11"), "frontends/typescript/0.4.11")
        self.assertEqual(CPP.tag("0.13.2"), "frontends/cpp/0.13.2")
        self.assertEqual(JAVA.tag("0.10.3"), "frontends/java/0.10.3")
        self.assertEqual(OCAML.tag("0.26.4"), "frontends/ocaml/0.26.4")

    def test_release_files_live_in_the_component(self) -> None:
        for component in release.COMPONENTS:
            self.assertEqual(component.release_file, f"{component.path}/RELEASE.md")
            self.assertEqual(component.changelog, f"{component.path}/CHANGELOG.md")

    def test_every_frontend_has_an_engine_bump_entry(self) -> None:
        self.assertIsNone(LIBHEGEL.engine_bump_entry)
        for frontend in release.FRONTENDS:
            self.assertIn("{version}", frontend.engine_bump_entry or "")

    def test_release_paths_cover_every_manifest_changelog_and_engine_pin(self) -> None:
        for component in release.COMPONENTS:
            for manifest in component.manifests:
                self.assertIn(manifest, release.RELEASE_PATHS)
            self.assertIn(component.changelog, release.RELEASE_PATHS)
            if component.engine_pin is not None:
                self.assertIn(component.engine_pin, release.RELEASE_PATHS)
            for doc in component.install_docs:
                self.assertIn(doc, release.RELEASE_PATHS)
        self.assertIn("Cargo.lock", release.RELEASE_PATHS)
        self.assertIn(TYPESCRIPT.engine_pin, release.RELEASE_PATHS)

    def test_release_paths_exist_in_the_checkout(self) -> None:
        for rel in release.RELEASE_PATHS:
            self.assertTrue((release.ROOT / rel).exists(), rel)

    def test_crates_match_the_manifests(self) -> None:
        for component in release.COMPONENTS:
            names = {
                release_name(release.ROOT / manifest) for manifest in component.manifests
            }
            self.assertEqual(names, set(component.crates), component.path)


def release_name(manifest: Path) -> str:
    if manifest.suffix == ".json":
        return json.loads(manifest.read_text())["name"]
    if manifest.name == "CMakeLists.txt":
        for line in manifest.read_text().splitlines():
            if line.startswith("project("):
                return line.removeprefix("project(").split()[0]
    if manifest.suffix == ".xml":
        # The pom's own artifactId: the first one outside the <parent> element.
        own = re.sub(r"<parent>.*?</parent>", "", manifest.read_text(), flags=re.DOTALL)
        return re.search(r"<artifactId>([^<]+)</artifactId>", own).group(1)
    if manifest.suffix == ".opam":
        return manifest.stem
    for line in manifest.read_text().splitlines():
        if line.startswith("name = "):
            return line.split('"')[1]
        if line.startswith("(name "):
            return line.removeprefix("(name ").rstrip(")")
    raise AssertionError(f"no package name in {manifest}")


class ReleaseTagsTest(unittest.TestCase):
    def test_rust_only_release_tags_only_the_rust_frontend(self) -> None:
        self.assertEqual(release.release_tags({RUST: "0.23.3"}), ["frontends/rust/0.23.3"])

    def test_c_release_tags_libhegel_first_then_the_frontends(self) -> None:
        self.assertEqual(
            release.release_tags({PYTHON: "0.2.0", RUST: "0.23.3", LIBHEGEL: "0.24.0"}),
            ["libhegel/0.24.0", "frontends/rust/0.23.3", "frontends/python/0.2.0"],
        )

    def test_libhegel_release_is_titled_after_libhegel(self) -> None:
        self.assertEqual(release.libhegel_release_title("0.24.0"), "libhegel v0.24.0")

    def test_commit_message_names_the_tags_and_skips_ci(self) -> None:
        message = release.release_commit_message(["libhegel/0.24.0", "frontends/rust/0.23.3"])
        self.assertEqual(
            message, "Release libhegel/0.24.0 and frontends/rust/0.23.3\n\n[skip ci]"
        )

    def test_release_branch_is_branch_safe(self) -> None:
        branch = release.release_branch(["libhegel/0.24.0", "frontends/python/0.2.0"])
        self.assertEqual(branch, "release/libhegel-0.24.0+frontends-python-0.2.0")


class ReleasePrDetailsTest(unittest.TestCase):
    def test_rust_only_release_names_its_tag(self) -> None:
        title, body = release.release_pr_details(["frontends/rust/0.23.3"])
        self.assertEqual(title, "Release frontends/rust/0.23.3")
        self.assertIn("after tagging frontends/rust/0.23.3 failed", body)
        self.assertIn("The tags and package publishes succeeded.", body)

    def test_c_release_names_every_tag(self) -> None:
        title, body = release.release_pr_details(
            ["libhegel/0.24.0", "frontends/rust/0.23.3", "frontends/python/0.2.0"]
        )
        self.assertEqual(
            title, "Release libhegel/0.24.0 and frontends/rust/0.23.3 and frontends/python/0.2.0"
        )
        self.assertIn("after tagging libhegel/0.24.0 and frontends/rust/0.23.3", body)


